 fs.writeFileSync(cfg.resultPath,JSON.stringify(report,null,2)+"\n",{flag:"wx"});console.log(JSON.stringify({state:report.state,passed:rows.filter(x=>x.status==="PASS").length,cleanup:cleanup.length,failure}));if(failure)process.exitCode=1;
